        used()[key] = next
    }
    private fun project(tool: String, value: Any?): Any? = clean(options.persistResult(tool, value)).also { charge("output_bytes", bytes(it).size.toDouble()) }
    private fun acknowledge(call: Map<String, Any?>, value: Any?) {
