        if (flag(state, "final")) return clean(state["final_result"])
        val started = System.nanoTime()
        if (num(state["deadline"]) == 0.0) state["deadline"] = now() + limits.getValue("elapsed_seconds") - num(used()["elapsed_seconds"])
        var failure: Throwable? = null; var result: Any? = null
