                deadlineMillis(); charge("turns", 1.0); charge("model_calls", 1.0); persist()
                val receipts = arr(state["receipts"]).map { item ->
                    val r = obj(clean(item)); Receipt(str(r["id"]), str(r["tool"]), str(r["arguments_hash"]), flag(r, "mutation"), r["result"], str(r["previous"]), str(r["hash"]))
                }
