                val pending = mutableListOf<Map<String, Any?>>()
                val invocations = mutableListOf<suspend (RequestOptions) -> Any?>()
                for (proposed in calls) {
                    if (proposed.id.isEmpty() || !seen.add(proposed.id) || proposed.tool !in allowed) throw refused("unknown tool or duplicate ID")
                    val call = proposed.copy(arguments = obj(clean(proposed.arguments)))
                    val descriptor = obj(registry[call.tool])
                    if (descriptor["execution"] != "buffered-json") throw refused("stream/upload operation is not qualified")
                    val fields = mutableSetOf<String>()
                    for (field in arr(descriptor["arguments"])) {
                        val argument = obj(field); val name = str(argument["name"]); fields.add(name)
                        val exists = call.arguments.containsKey(name)
                        if (!exists && flag(argument, "required")) throw refused("required argument missing")
                        if (!exists) continue
                        if (flag(argument, "caller_only")) throw refused("header/cookie arguments require caller configuration")
                        validate(call.arguments[name], obj(argument["schema"]), schemas)
                    }
                    if (!fields.containsAll(call.arguments.keys)) throw refused("unknown argument; request options forbidden")
                    invocations.add(prepare(call)); pending.add(mapOf("id" to call.id, "tool" to call.tool, "arguments_hash" to hash(bytes(call.arguments)), "mutation" to flag(descriptor, "mutation")))
                }
                charge("tool_calls", pending.size.toDouble())
                for (call in pending) if (flag(call, "mutation") && !kotlinx.coroutines.withTimeout(deadlineMillis()) { options.approveWrite(str(call["tool"]), str(call["arguments_hash"])) }) throw refused("explicit write approval required")
                kotlinx.coroutines.currentCoroutineContext().ensureActive(); val timeout = deadlineMillis()
                val bound = minOf(67108864.0, limits.getValue("output_bytes") - num(used()["output_bytes"])).toInt()
                if (bound < 1) throw refused("output budget exceeded")
                state["pending"] = pending; persist()
                val requestOptions = RequestOptions(agentSessionMaxResponseBytes = bound, agentSessionTimeout = java.time.Duration.ofMillis(timeout))
                val values = kotlinx.coroutines.withTimeout(timeout) {
                    kotlinx.coroutines.coroutineScope {
                        invocations.map { invocation -> async(kotlinx.coroutines.Dispatchers.IO) { invocation(requestOptions) } }.awaitAll()
                    }
                }
                for (index in values.indices) acknowledge(pending[index], values[index])
            }
        } catch (error: Throwable) { failure = error }
        finally {
            val elapsed = num(used()["elapsed_seconds"]) + (System.nanoTime() - started) / 1e9
            mutable(state["observed_usage"])["elapsed_seconds"] = elapsed
            used()["elapsed_seconds"] = minOf(limits.getValue("elapsed_seconds"), elapsed)
            try { persist() } catch (storage: Throwable) { failure?.let { storage.addSuppressed(it) }; failure = storage }
            try {
                kotlinx.coroutines.withContext(kotlinx.coroutines.NonCancellable) {
                    kotlinx.coroutines.withTimeout(maxOf(1, minOf(1000.0, limits.getValue("elapsed_seconds") * 1000).toLong())) { provider.close() }
                }
            } catch (closeError: Throwable) {
                val wrapped = refused("provider cleanup failed; callbacks remain caller-owned", closeError)
                failure?.let { wrapped.addSuppressed(it) }; failure = wrapped
            }
        }
        failure?.let { error ->
            if (arr(state["pending"]).any { flag(obj(it), "mutation") }) throw SessionException("explicit reconciliation required; no call will be retried", error, true)
            throw error
        }
        return result
    }
}
